52	task	Task (Subagent)	Delegate a task to a specialized subagent for execution.\n\nUse this tool to spawn work to configured subagents. The subagent will\nexecute the task and return the result. This enables parallel processing\nand specialization.\n\nArgs:\n    description: Clear description of the task to perform\n    subagent_type: Type of subagent to use (e.g., "research", "code", "writer", "general")\n    context: Additional context or information for the subagent\n    expected_output: Description of expected output format/content\n\nReturns:\n    Result from the subagent execution\n\nExample:\n    >>> task(\n    ...     description="Research the latest trends in AI image generation",\n    ...     subagent_type="research",\n    ...     context="Focus on diffusion models released in 2024",\n    ...     expected_output="A summary with key findings and links"\n    ... )	python_function	custom	{"function_name": "task", "code": "# --- imports ---\\n\\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\\n\\n# --- logger ---\\n\\nimport logging\\n\\nlogger = logging.getLogger(\\"langconfig.builtin_tool\\")\\n\\ndef task(\\n    description: str,\\n    subagent_type: str = \\"general\\",\\n    context: str = \\"\\",\\n    expected_output: str = \\"\\"\\n) -> str:\\n    \\"\\"\\"\\n    Delegate a task to a specialized subagent for execution.\\n\\n    Use this tool to spawn work to configured subagents. The subagent will\\n    execute the task and return the result. This enables parallel processing\\n    and specialization.\\n\\n    Args:\\n        description: Clear description of the task to perform\\n        subagent_type: Type of subagent to use (e.g., \\"research\\", \\"code\\", \\"writer\\", \\"general\\")\\n        context: Additional context or information for the subagent\\n        expected_output: Description of expected output format/content\\n\\n    Returns:\\n        Result from the subagent execution\\n\\n    Example:\\n        >>> task(\\n        ...     description=\\"Research the latest trends in AI image generation\\",\\n        ...     subagent_type=\\"research\\",\\n        ...     context=\\"Focus on diffusion models released in 2024\\",\\n        ...     expected_output=\\"A summary with key findings and links\\"\\n        ... )\\n    \\"\\"\\"\\n    logger.info(f\\"[TASK DELEGATION] Spawning subagent task: {description[:100]}...\\")\\n    logger.info(f\\"  subagent_type: {subagent_type}\\")\\n    logger.info(f\\"  context: {context[:100] if context else 'None'}...\\")\\n\\n    # This is a placeholder - actual subagent execution is handled by the DeepAgents framework\\n    # The framework intercepts this tool call and routes it to the appropriate subagent\\n    # based on the subagent configurations in the DeepAgentConfig\\n\\n    # For now, return a message indicating the tool was called\\n    # The actual implementation is in the DeepAgents middleware\\n    return f\\"\\"\\"[SUBAGENT TASK QUEUED]\\nTask: {description}\\nType: {subagent_type}\\nContext: {context if context else 'None'}\\nExpected Output: {expected_output if expected_output else 'Any relevant output'}\\n\\nNote: This task has been queued for subagent execution. The DeepAgents framework\\nwill route this to the appropriate configured subagent. If no subagents are\\nconfigured, this task will be executed by the main agent.\\"\\"\\"", "args_schema": {"description": {"type": "string", "description": ""}, "subagent_type": {"type": "string", "description": "", "default": "general"}, "context": {"type": "string", "description": "", "default": ""}, "expected_output": {"type": "string", "description": "", "default": ""}}}	{"type": "object", "properties": {"description": {"type": "string", "description": ""}, "subagent_type": {"type": "string", "description": "", "default": "general"}, "context": {"type": "string", "description": "", "default": ""}, "expected_output": {"type": "string", "description": "", "default": ""}}, "required": ["description"]}	string	\N	t	t	builtin-seeder	f	\N	0	\N	0	\N	1.0.0	\N	delegation	t	\N	["builtin", "delegation"]	2026-08-01 14:44:18.034577+00	2026-08-15 08:05:00.518177+00	{"category": "agents", "order": 16, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}
86	update_agent_prompt	Update Agent Prompt	Update the system prompt of an existing DeepAgent by id (find ids with pg_list_agents). Follows LangChain agent specs.	python_function	custom	{"function_name": "update_agent_prompt", "code": "# --- imports ---\\n\\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\\n\\n\\ndef update_agent_prompt(agent_id: int, system_prompt: str) -> str:\\n    \\"\\"\\"Update the system prompt of an existing DeepAgent (find ids with pg_list_agents).\\n\\n    Args:\\n        agent_id: Numeric agent id (from pg_list_agents)\\n        system_prompt: The new COMPLETE system prompt following LangChain agent specs\\n    \\"\\"\\"\\n    from db.database import SessionLocal\\n    from models.deep_agent import DeepAgentTemplate\\n\\n    db = SessionLocal()\\n    try:\\n        agent = db.query(DeepAgentTemplate).filter(DeepAgentTemplate.id == agent_id).first()\\n        if not agent:\\n            return f\\"\\\\u274c Agent with id={agent_id} not found. Use pg_list_agents to find valid IDs.\\"\\n        cfg = dict(agent.config or {})\\n        cfg[\\"system_prompt\\"] = system_prompt.strip()\\n        agent.config = cfg\\n        agent.lock_version = (agent.lock_version or 0) + 1  # bump optimistic-lock\\n        db.commit()\\n        return f\\"\\\\u2705 Agent '{agent.name}' (id={agent.id}) system prompt updated.\\"\\n    except Exception as e:\\n        db.rollback()\\n        return f\\"\\\\u274c Failed to update prompt: {e}\\"\\n    finally:\\n        db.close()\\n", "args_schema": {"agent_id": {"type": "integer", "description": "Numeric agent id (from pg_list_agents)"}, "system_prompt": {"type": "string", "description": "The new COMPLETE system prompt"}}}	{"type": "object", "properties": {"agent_id": {"type": "integer", "description": "Numeric agent id (from pg_list_agents)"}, "system_prompt": {"type": "string", "description": "The new COMPLETE system prompt"}}, "required": ["agent_id", "system_prompt"]}	string	null	t	f	